import { XmlElement } from '../xml/xml-builder';
import { TextSegment } from '../../text-segmentation/text-segmentation';

/**
 * Represents a file entry to be packaged in the hybrid book archive.
 */
export interface ExportFileEntry {
  path: string,
  content: File | Blob | string | Uint8Array | ArrayBuffer,
  fallbackUrl?: string | null,
}

/**
 * Contextual data provided to a text record exporter.
 */
export interface TextExportContext {
  file: File,
  fallbackUrl?: string | null,
  segments: readonly TextSegment[],
  groupName: string,
}

/**
 * Result data generated by a text record exporter.
 */
export interface TextExportResult {
  mediaElement: XmlElement,
  files: ExportFileEntry[],
  totalPhrases: number,
}

/**
 * Extensible contract for exporting hybrid book text records.
 */
export interface TextRecordExporter {
  readonly format: string,

  /**
   * Generates the XML media element and file entries for the text record.
   *
   * @param context The text export context.
   * @returns A promise resolving to the text export result.
   */
  exportText(context: TextExportContext): Promise<TextExportResult>,
}
